// === Tab: pixel_magnets ===

  let imageScale;
  let dotDensity =3.1; // higher ratios = more dots
  let damping = 0.4;
  let kRadiusFactor = 0.5;
  let kSpeed = 3.0;
  let minDistFactor = 2.5; // area of influence - smaller numbers make rendering go faster
  let radiusRatio = 5;
  let radiusOffset = 0.1;
  let nbrParticles = 12500;
  let particlesPerFrame = 8;  
  let reference; 


  class Particle
  {
    x, y, vx, vy, rad, vrad;
    fx, fy, wt;

    constructor(_x, _y)
    {
      vx = 0;
      vy = 0;
      x = _x;
      y = _y;
      rad = 1;
      vrad = 1;
    }
  }

  let particles;

  let minRadius, maxRadius, medRadius;
  let pixelCount = 0;

  function setup()
  {
    createCanvas(500, 500);


    reference = loadImage("https://openprocessing.org/sketch/1809796/files/d.png");

    let dwidth = 500;
    let dheight = 500;
    imageScale = width/float(dwidth);

    particles = new Array(nbrParticles);


    frameRate(55);
    smooth();
    stroke(0);
    fill(0);
    ellipseMode(CENTER);

    let medArea = (width*height)/nbrParticles;
    medRadius = sqrt(medArea/PI);
    minRadius = medRadius;
    maxRadius = medRadius*medRadius*1;
    background(255);
  }

  function doPhysics()
  {


    for (i = 0; i < pixelCount; ++i) {
      let px = int(particles[i].x / imageScale);
      let py = int(particles[i].y / imageScale);
      if (px >= 0 && px < reference.width && py >= 0 && py < reference.height) {
        let v = int(red)(reference.pixels[ py*reference.width + px ]);
        particles[i].rad = map(v/255.0, 0, 1, minRadius, maxRadius);
        particles[i].vrad = radiusOffset + radiusRatio * (255 - v) / 255 ;
      }
    }


    for (i = 0; i < pixelCount; ++i) {
      let p = particles[i];
      p.fx = p.fy = p.wt = 0;

      p.vx *= damping;
      p.vy *= damping;
    }

    // Particle -> particle interactions
    for (i = 0; i < pixelCount-1; ++i) {
      var p = particles[i];
      for (j = i+1; j < pixelCount; ++j) {
        let pj = particles[j];
        if (i== j || Math.abs(pj.x - p.x) > p.rad*minDistFactor ||
          Math.abs(pj.y - p.y) > p.rad*minDistFactor)
          continue;

        let dx = p.x - pj.x;
        let dy = p.y - pj.y;
        let distance = Math.sqrt(dx*dx+dy*dy);

        let maxDist = (p.rad + pj.rad);
        let diff = maxDist - distance;
        if (diff > 0) {
          let scle = diff/maxDist;
          scle = scle*scle;
          p.wt += scle;
          pj.wt += scle;
          scle = scle*kSpeed/distance;
          p.fx += dx*scle;
          p.fy += dy*scle;
          pj.fx -= dx*scle;
          pj.fy -= dy*scle;
        }
      }
    }

    for (i = 0; i < pixelCount; ++i) {
      var p = particles[i];

      // keep within edges
      var dx, dy, distance, scle, diff;
      var maxDist = p.rad;
      // left edge  
      distance = dx = p.x - 0;    
      dy = 0;
      diff = maxDist - distance;
      if (diff > 0) {
        scle = diff/maxDist;
        scle = scle*scle;
        p.wt += scle;
        scle = scle*kSpeed/distance;
        p.fx += dx*scle;
        p.fy += dy*scle;
      }
      // right edge  
      dx = p.x - width;    
      dy = 0;
      distance = -dx;
      diff = maxDist - distance;
      if (diff > 0) {
        scle = diff/maxDist;
        scle = scle*scle;
        p.wt += scle;
        scle = scle*kSpeed/distance;
        p.fx += dx*scle;
        p.fy += dy*scle;
      }
      // top edge
      distance = dy = p.y - 0;    
      dx = 0;
      diff = maxDist - distance;
      if (diff > 0) {
        scle = diff/maxDist;
        scle = scle*scle;
        p.wt += scle;
        scle = scle*kSpeed/distance;
        p.fx += dx*scle;
        p.fy += dy*scle;
      }
      // bot edge  
      dy = p.y - height;    
      dx = 0;
      distance = -dy;
      diff = maxDist - distance;
      if (diff > 0) {
        scle = diff/maxDist;
        scle = scle*scle;
        p.wt += scle;
        scle = scle*kSpeed/distance;
        p.fx += dx*scle;
        p.fy += dy*scle;
      }
      if (p.wt > 0) {
        p.vx += p.fx/p.wt;
        p.vy += p.fy/p.wt;
      }
      p.x += p.vx;
      p.y += p.vy;
    }
  }


  function draw()
  {
    background(255);
    //if (pixelCount % 100 == 0) println(pixelCount);

    if (pixelCount < nbrParticles) {
      for (i = 0; i < particlesPerFrame; i++) {
        particles[pixelCount++] = new Particle(random(width), random(height));
      }
    }


    doPhysics();

    for (i = 0; i < pixelCount; ++i) {
      strokeWeight(particles[i].vrad);
      point(particles[i].x, particles[i].y);
    }
  }

